import {canvasSettings} from './canvas.js';
const id=()=>crypto.randomUUID();
export const clone=value=>JSON.parse(JSON.stringify(value));
export function createBoard(){const layer=id();return {bounds:{x:-800,y:-500,w:1600,h:1000},canvas:canvasSettings(),arrowRoute:'smart',layers:[{id:layer,name:'Layer 1',visible:true,locked:false}],objects:[],activeLayer:layer};}
export function layerOf(board,object){return board.layers.find(layer=>layer.id===object.layer);}
export function editable(board,object){const layer=layerOf(board,object);return !!layer&&layer.visible&&!layer.locked;}
export function expand(board,direction){if(!['top','right','bottom','left'].includes(direction))throw new Error('Unknown direction');const b=board.bounds;if(direction==='left'){b.x-=800;b.w+=800}if(direction==='right')b.w+=800;if(direction==='top'){b.y-=600;b.h+=600}if(direction==='bottom')b.h+=600;return {...b};}
export function contain(board,rect){const b=board.bounds;while(rect.x<b.x)expand(board,'left');while(rect.y<b.y)expand(board,'top');while(rect.x+rect.w>b.x+b.w)expand(board,'right');while(rect.y+rect.h>b.y+b.h)expand(board,'bottom');}
export function addObject(board,values){const layer=board.layers.find(layer=>layer.id===board.activeLayer);if(!layer||layer.locked||!layer.visible)throw new Error('Choose a visible, unlocked layer first.');const object={id:id(),layer:layer.id,color:'#292536',...(values.type==='arrow'?{route:board.arrowRoute||'smart'}:{}),...values};board.objects.push(object);if(object.type!=='arrow')contain(board,object);return object;}
export function connect(board,start,end,values={}){const a=board.objects.find(o=>o.id===start),b=board.objects.find(o=>o.id===end);if(!a||!b||a.type==='arrow'||b.type==='arrow'||a.id===b.id)throw new Error('Select two different text or image objects.');if(!editable(board,a)||!editable(board,b))throw new Error('Both objects must be on visible, unlocked layers.');return addObject(board,{type:'arrow',start:{x:a.x+a.w/2,y:a.y+a.h/2,objectId:a.id},end:{x:b.x+b.w/2,y:b.y+b.h/2,objectId:b.id},stroke:2.5,...values});}
function endpoint(board,point){const object=board.objects.find(o=>o.id===point.objectId);return object&&object.type!=='arrow'?{x:object.x+object.w/2,y:object.y+object.h/2,object}:point;}
function border(point,towards){if(!point.object)return {x:point.x,y:point.y};const dx=towards.x-point.x,dy=towards.y-point.y;if(!dx&&!dy)return {x:point.x,y:point.y};const scale=1/Math.max(Math.abs(dx)/(point.object.w/2+5),Math.abs(dy)/(point.object.h/2+5));return {x:point.x+dx*scale,y:point.y+dy*scale};}
export function arrowPoints(board,arrow,approach={}){const a=endpoint(board,arrow.start),b=endpoint(board,arrow.end);return {start:border(a,approach.start||b),end:border(b,approach.end||a)};}
export function visibleObject(board,object){if(!layerOf(board,object)?.visible)return false;if(object.type==='arrow')return [object.start,object.end].every(p=>!p.objectId||!board.objects.some(o=>o.id===p.objectId)||layerOf(board,board.objects.find(o=>o.id===p.objectId))?.visible);return true;}
export function removeObject(board,objectId){board.objects=board.objects.filter(o=>o.id!==objectId&&!(o.type==='arrow'&&(o.start.objectId===objectId||o.end.objectId===objectId)));}
export function moveLayer(board,layerId,offset){const i=board.layers.findIndex(l=>l.id===layerId),j=i+offset;if(i<0||j<0||j>=board.layers.length)return false;const [layer]=board.layers.splice(i,1);board.layers.splice(j,0,layer);return true;}
export function removeLayer(board,layerId){if(board.layers.length===1)throw new Error('Keep at least one layer.');const ids=board.objects.filter(o=>o.layer===layerId).map(o=>o.id);ids.forEach(objectId=>removeObject(board,objectId));board.layers=board.layers.filter(l=>l.id!==layerId);if(board.activeLayer===layerId)board.activeLayer=board.layers.at(-1).id;}
export function objectName(object){if(object.type==='text')return object.text.replace(/\s+/g,' ').trim().slice(0,50)||'Text';if(object.type==='image')return object.name||'Image';if(object.type==='pen')return 'Drawing';if(object.type==='shape')return (object.shape||'Shape').replace(/^./,c=>c.toUpperCase());return 'Arrow';}
export class History{constructor(limit=60){this.limit=limit;this.past=[];this.future=[];}record(before,after){if(JSON.stringify(before)===JSON.stringify(after))return;this.past.push(clone(before));if(this.past.length>this.limit)this.past.shift();this.future=[];}undo(current){if(!this.past.length)return current;this.future.push(clone(current));return this.past.pop();}redo(current){if(!this.future.length)return current;this.past.push(clone(current));return this.future.pop();}}
